with latest_match as (select s.*, x.amount, x.order_shipping_fee from stores s left join lateral (select c.amount, c.shipping_fee as order_shipping_fee from orders c where c.store_id = s.id and c.order_date <= s.opened_date order by c.order_date desc, c.id desc limit 1) x on true), cleaned as (select id, store_name, region, opened_date, sqft, amount, order_shipping_fee, concat(region, '/', store_name) region_store_name, coalesce(region, 'UNKNOWN') region_clean from latest_match where opened_date >= date '2024-03-05' and region is not null), with_windows as (select *, row_number() over w_hist event_seq, avg(sqft) over (order by order_shipping_fee, id rows between 2 preceding and current row) sqft_avg_2, avg(sqft) over (partition by region order by order_shipping_fee, id rows between 6 preceding and 1 preceding) sqft_avg_6_prior, lead(amount, 2) over (partition by region order by order_shipping_fee, id) next_amount from cleaned window w_hist as (partition by region order by amount desc, id)), with_windows_stores as (select *, ntile(5) over (partition by region order by event_seq desc, id) event_seq_bucket, ntile(5) over (partition by region order by event_seq, id) event_seq_bucket_2, lag(amount, 2) over w_grp prev_amount, ntile(4) over w_recent sqft_bucket from with_windows window w_grp as (order by sqft, id), w_recent as (partition by region order by sqft desc, id)), enriched as (select *, round(event_seq_bucket / sum(event_seq_bucket) over (partition by region), 4) event_seq_bucket_share, avg(sqft_avg_6_prior) over (partition by region order by prev_amount, id rows between 6 preceding and 1 preceding) sqft_avg_6_prior_avg_6_prior, row_number() over (partition by region order by sqft_avg_6_prior, id) seq_no, row_number() over (order by amount desc, id) seq_no_2, lead(next_amount, 1) over (partition by region order by next_amount, id) next_next_amount from with_windows_stores), latest as (select * from (select *, row_number() over (partition by region order by sqft desc, id) as rn from enriched) t where rn = 1), scored as (select *, count(prev_amount) over (partition by region) region_count_prev_amount, round(seq_no_2 / sum(seq_no_2) over (partition by region), 4) seq_no_2_share, dense_rank() over w_ordered seq_no_dense_rank from latest window w_ordered as (partition by region order by seq_no desc nulls last)) select id, store_name, region, opened_date, order_shipping_fee, region_store_name, region_clean, event_seq, next_amount, case when region rlike '^(North|Central)$' then 'PRIORITY' when region rlike '^(South|East)$' then 'GROUP_B' else 'OTHER_ZONE' end as region_zone from scored order by event_seq
